namespace CheckoutPricing.Domain;

public sealed class DiscountPolicy
{
    private const int LoyaltyMinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    private readonly LoyaltyDiscountPolicy _loyalty = new();

    public int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCentsFor(subtotalCents, loyaltyTier);
        var promoCents = PromoCentsFor(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }

    private int LoyaltyCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < LoyaltyMinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyCapCents, _loyalty.DiscountCentsFor(subtotalCents, loyaltyTier));

    private static int PromoCentsFor(string? promoCode, int remainingCents)
    {
        if (Is(promoCode, "WELCOME5"))
        {
            return Welcome5Cents;
        }

        return Is(promoCode, "SUMMER10") ? Math.Min(Summer10CapCents, remainingCents / 10) : 0;
    }

    private static bool Is(string? promoCode, string expected) =>
        string.Equals(promoCode, expected, StringComparison.OrdinalIgnoreCase);
}

namespace CheckoutPricing.Domain;

public sealed class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express
            ? ExpressFeeCentsFor(loyaltyTier)
            : StandardFeeCentsFor(payableTotalCents, loyaltyTier);

    private static int ExpressFeeCentsFor(LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier)
    {
        var travelsFree = loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum
            || payableTotalCents >= FreeStandardFromCents;
        return travelsFree ? 0 : StandardFeeCents;
    }
}

